// Dynamic array formulas in the editor: a formula typed into a cell spills, the cells it fills
// show where their value comes from, and something typed into them is in its way (#SPILL!).
// Every workbook is generated by code; results are read from the model.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/** A1:A4 = 4, 2, 3, 1. */
const workbook = once(() =>
  buildXlsx({ sheets: [{ name: 'Data', xml: worksheetXml(`<sheetData><row r="1">${num('A1', 4)}</row><row r="2">${num('A2', 2)}</row><row r="3">${num('A3', 3)}</row><row r="4">${num('A4', 1)}</row></sheetData>`) }] }),
);

async function mount(page: Page, bytes: Uint8Array): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64 }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, { locale: 'en-US' }, 'host');
    },
    { base64: Buffer.from(bytes).toString('base64') },
  );
  await expect(page.locator('#host .bym-canvas')).toBeVisible();
}

const select = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    (window as any).__editor.view.select(api.parseRange(ref));
  }, ref);

/** Types into the active cell through the page, as a user does, and confirms with Enter. */
async function typeInto(page: Page, ref: string, text: string): Promise<void> {
  await select(page, ref);
  await page.locator('#host .bym-input').focus();
  await page.keyboard.type(text);
  await page.keyboard.press('Enter');
}

const values = (page: Page, refs: string[]) =>
  page.evaluate((refs) => {
    const api = (window as any).BymOffice;
    const view = (window as any).__editor.view;
    const sheet = view.workbook.sheets[view.activeSheet];
    return refs.map((ref) => {
      const at = api.parseCellRef(ref);
      const found = api.getCell(sheet, at.row, at.col);
      return found ? found.value : null;
    });
  }, refs);

test('a typed formula spills; its cells show the formula greyed, and something typed there blocks it', async ({ page }) => {
  await mount(page, await workbook());
  await typeInto(page, 'C1', '=SORT(A1:A4)');
  await expect.poll(() => values(page, ['C1', 'C2', 'C3', 'C4'])).toEqual([1, 2, 3, 4]);

  // A cell of the spill: the formula bar shows where its value comes from, greyed.
  await select(page, 'C3');
  const content = page.locator('#host .bym-formula-input');
  await expect(content).toHaveValue('=SORT(A1:A4)');
  await expect(content).toHaveAttribute('data-spilled', '');
  const spilled = await page.evaluate(() => {
    const from = (window as any).__editor.view.spilledFrom;
    return from ? { row: from.row, col: from.col, range: (window as any).BymOffice.rangeName(from.range) } : null;
  });
  expect(spilled).toEqual({ row: 0, col: 2, range: 'C1:C4' });
  // The formula's own cell is no spilled cell.
  await select(page, 'C1');
  await expect(content).toHaveValue('=SORT(A1:A4)');
  await expect(content).not.toHaveAttribute('data-spilled', '');

  // Something typed into the spill is in the way.
  await typeInto(page, 'C3', 'x');
  await expect.poll(() => values(page, ['C1', 'C2', 'C3', 'C4'])).toEqual(['#SPILL!', null, 'x', null]);
  // Undone, the formula spills again.
  await page.locator('#host .bym-input').focus();
  await page.keyboard.press('Control+z');
  await expect.poll(() => values(page, ['C1', 'C2', 'C3', 'C4'])).toEqual([1, 2, 3, 4]);
});

test('"A1#" reads the whole spill; a spill that grows takes its readers along', async ({ page }) => {
  await mount(page, await workbook());
  await typeInto(page, 'B1', '=SEQUENCE(A2)');
  await typeInto(page, 'D1', '=SUM(B1#)');
  await expect.poll(() => values(page, ['B1', 'B2', 'B3', 'D1'])).toEqual([1, 2, null, 3]);
  await typeInto(page, 'A2', '3');
  await expect.poll(() => values(page, ['B1', 'B2', 'B3', 'D1'])).toEqual([1, 2, 3, 6]);
  // The formula as it is shown, and as the file stores it.
  await select(page, 'D1');
  await expect(page.locator('#host .bym-formula-input')).toHaveValue('=SUM(B1#)');
  const stored = await page.evaluate(() => {
    const view = (window as any).__editor.view;
    return (window as any).BymOffice.getCell(view.workbook.sheets[view.activeSheet], 0, 3).formula.text;
  });
  expect(stored).toBe('SUM(_xlfn.ANCHORARRAY(B1))');
});
